import {Button, Heading} from '@primer/react'
import {clsx} from 'clsx'
import type {PropsWithChildren} from 'react'

import styles from './ClaimCustomizationSection.module.css'
import sudo from '@github-ui/sudo'
import {useBannerContext} from '../context/BannerProvider'

export function ClaimCustomizationSection({
  title,
  subtitle,
  className,
  onSave,
  isSaving = false,
  showSaveButton = true,
  children,
}: PropsWithChildren<{
  title: string
  subtitle: string
  onSave: () => void
  isSaving?: boolean
  showSaveButton?: boolean
  className?: string
}>) {
  const {setBanner} = useBannerContext()

  const onSaveSection = async () => {
    if (!(await sudo())) {
      setBanner({message: 'Unauthorized', type: 'critical'})
      return
    }

    onSave()
  }

  return (
    <div className={styles.sectionContainer}>
      <Heading as="h3" className={styles.sectionTitle}>
        {title}
      </Heading>
      <p className={styles.subtitleText}>{subtitle}</p>
      <div className={clsx(styles.sectionContentContainer, className)}>{children}</div>
      {showSaveButton && (
        <Button className="tmp-mt-3" variant="primary" onClick={onSaveSection} disabled={isSaving}>
          {isSaving ? 'Saving...' : `Save ${title.toLocaleLowerCase()}`}
        </Button>
      )}
    </div>
  )
}
