export const getRepositoryOidcConfigurationPath = ({owner, repo}: {owner: string; repo: string}): string => {
  return `/${encodeURIComponent(owner)}/${encodeURIComponent(repo)}/settings/actions/oidc-configuration`
}

export const getOrganizationOidcConfigurationPath = ({org}: {org: string}): string => {
  return `/organizations/${encodeURIComponent(org)}/settings/actions/oidc-configuration`
}

export const getEnterpriseOidcConfigurationPath = ({business}: {business: string}): string => {
  return `/enterprises/${encodeURIComponent(business)}/settings/actions/oidc-configuration`
}

export const getSearchEnterpriseCustomPropertiesPath = ({business}: {business: string}): string => {
  return `/enterprises/${encodeURIComponent(business)}/settings/actions/oidc-configuration/custom-properties/search`
}

export const getSearchOrganizationCustomPropertiesPath = ({org}: {org: string}): string => {
  return `/organizations/${encodeURIComponent(org)}/settings/actions/oidc-configuration/custom-properties/search`
}

export const getEnterpriseCustomPropertiesPath = ({business}: {business: string}): string => {
  return `/enterprises/${encodeURIComponent(business)}/settings/custom-properties`
}

export const getOrganizationCustomPropertiesPath = ({org}: {org: string}): string => {
  return `/organizations/${encodeURIComponent(org)}/settings/custom-properties`
}
