import {useParams} from '@github-ui/react-router'
import type {SettingsLevel} from '../types'
import {
  getEnterpriseOidcConfigurationPath,
  getOrganizationOidcConfigurationPath,
  getRepositoryOidcConfigurationPath,
} from '../paths'

interface ConfigurationSource {
  settingsLevel: SettingsLevel
  sourceName: string
  basePath: string
}

type Params = {
  business?: string
  org?: string
  owner?: string
  repo?: string
}

export function useConfigurationSource(): ConfigurationSource {
  const {business, org, owner, repo} = useParams<Params>()

  if (business) {
    return {
      settingsLevel: 'enterprise',
      sourceName: business,
      basePath: getEnterpriseOidcConfigurationPath({business}),
    }
  }

  if (org) {
    return {
      settingsLevel: 'organization',
      sourceName: org,
      basePath: getOrganizationOidcConfigurationPath({org}),
    }
  }

  if (owner && repo) {
    return {
      settingsLevel: 'repository',
      sourceName: `${owner}/${repo}`,
      basePath: getRepositoryOidcConfigurationPath({owner, repo}),
    }
  }

  throw new Error('Route must include either :business, :org, or :owner/:repo parameter')
}
