import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {useBannerContext} from '../context/BannerProvider'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {useConfigurationSource} from './use-configuration-source'

interface OIDCMutationOptions {
  pathSuffix: string
  onSuccess: () => void
}

export function useOIDCConfigurationMutation<TPayload>({
  pathSuffix,
  onSuccess,
}: OIDCMutationOptions): UseMutationResult<void, Error, TPayload> {
  const {setBanner, bannerRef} = useBannerContext()
  const {basePath} = useConfigurationSource()

  return useMutation({
    mutationFn: (body: TPayload) => saveConfiguration<TPayload>(`${basePath}/${pathSuffix}`, body),
    onError: error => {
      setBanner({message: error.message, type: 'critical'})
    },
    onSuccess,
    onSettled: () => {
      const banner = bannerRef?.current
      if (!banner) return

      // Get the banner's position relative to the viewport
      const rect = banner.getBoundingClientRect()
      // Check if the banner is fully visible in the viewport
      const isVisible = rect.bottom > 0 && rect.top < window.innerHeight

      if (!isVisible) {
        banner.scrollIntoView({behavior: 'smooth', block: 'nearest'})
      }
    },
  })
}

async function saveConfiguration<TPayload>(path: string, body: TPayload): Promise<void> {
  const response = await reactFetchJSON(path, {
    method: 'PUT',
    body,
  })

  if (response.ok) {
    return
  }

  let errorMessage: string | undefined
  try {
    const data = (await response.json()) as {error?: string}
    errorMessage = data?.error
  } catch {
    errorMessage = 'Something went wrong'
  }

  throw new Error(errorMessage)
}
