import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {organizationOidcConfigurationRoute} from './organization-oidc-configuration-route'
import {SubjectClaimCustomization} from '../components/SubjectClaimCustomization'
import {useEffect} from 'react'
import {useBannerContext} from '../context/BannerProvider'
import {CustomPropertyInclusions} from '../components/CustomPropertyInclusions'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'

export function OrganizationOidcConfiguration() {
  const {
    data: {
      subjectClaimKeys,
      includedProperties,
      propertyCount,
      enterprise,
      useImmutableSubject,
      isImmutableSubClaimAutoEnabled,
      showImmutableSubjectClaim,
    },
  } = useRouteQuery(organizationOidcConfigurationRoute, 'mainQuery')
  const {banner, bannerRef} = useBannerContext()
  /* eslint-disable-next-line @github-ui/github-monorepo/no-use-feature-flags --
     TODO: Migrate to isFeatureEnabled from @github-ui/feature-flags. See
     https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
  const showPropertyInclusions = useFeatureFlag('actions_oidc_custom_repo_properties')

  useEffect(() => bannerRef?.current?.focus(), [banner, bannerRef])

  return (
    <>
      <SubjectClaimCustomization
        template={subjectClaimKeys}
        showImmutableSubjectOption={showImmutableSubjectClaim}
        useImmutableSubject={showImmutableSubjectClaim ? useImmutableSubject : undefined}
        isImmutableSubClaimAutoEnabled={showImmutableSubjectClaim ? isImmutableSubClaimAutoEnabled : undefined}
      />
      {showPropertyInclusions && (
        <CustomPropertyInclusions
          includedProperties={includedProperties}
          propertyCount={propertyCount}
          source={enterprise}
        />
      )}
    </>
  )
}
