import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {actionsOidcConfigurationAppBuilder} from './config/app-builder'

import {organizationOidcConfigurationRoute} from './routes/organization-oidc-configuration-route'
import {OrganizationOidcConfiguration} from './routes/OrganizationOidcConfiguration'
import {enterpriseOidcConfigurationRoute} from './routes/enterprise-oidc-configuration-route'
import {EnterpriseOidcConfiguration} from './routes/EnterpriseOidcConfiguration'
import {repositoryOidcConfigurationRoute} from './routes/repository-oidc-configuration-route'
import {RepositoryOidcConfiguration} from './routes/RepositoryOidcConfiguration'
import {layoutRoute} from './routes/layout-route'
import {LayoutRoute} from './routes/LayoutRoute'

export const actionsOidcConfigurationApp = actionsOidcConfigurationAppBuilder.createDataRouterAppFromRoutes([
  layoutRoute.toRoute({
    Component: LayoutRoute,
    children: [
      organizationOidcConfigurationRoute.toRoute({Component: OrganizationOidcConfiguration}),
      enterpriseOidcConfigurationRoute.toRoute({Component: EnterpriseOidcConfiguration}),
      repositoryOidcConfigurationRoute.toRoute({Component: RepositoryOidcConfiguration}),
    ],
  }),
])
registerDataRouterApp(actionsOidcConfigurationApp)
