import {Checkbox, FormControl, Link, Textarea} from '@primer/react'
import {CopyToClipboardButton} from '@github-ui/copy-to-clipboard/Button'
import {ClaimCustomizationSection} from './ClaimCustomizationSection'
import {useBannerContext} from '../context/BannerProvider'
import {useOIDCConfigurationMutation} from '../hooks/use-oidc-configuration-mutation'
import {useState} from 'react'
import type {SubjectClaimPayload} from '../types'
import styles from './SubjectClaimCustomization.module.css'
import {useDebounce} from '@github-ui/use-debounce'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import {useConfigurationSource} from '../hooks/use-configuration-source'

type SubjectClaimCustomizationProps = {
  template?: string[]
  showDefaultTemplateOption?: boolean
  showImmutableSubjectOption?: boolean
  useDefaultTemplate?: boolean
  useImmutableSubject?: boolean
  subClaimPrefix?: string
  immutableSubClaimPrefix?: string
  isImmutableSubClaimAutoEnabled?: boolean
}

export function SubjectClaimCustomization({
  template: initialTemplate,
  showDefaultTemplateOption = false,
  showImmutableSubjectOption = false,
  useDefaultTemplate: initialUseDefaultTemplate = false,
  useImmutableSubject: initialUseImmutableSubject = false,
  subClaimPrefix,
  immutableSubClaimPrefix,
  isImmutableSubClaimAutoEnabled = false,
}: SubjectClaimCustomizationProps) {
  const [template, setTemplate] = useState(initialTemplate?.join(', ') || '')
  const [useDefaultTemplate, setUseDefaultTemplate] = useState(initialUseDefaultTemplate)
  const [useImmutableSubject, setUseImmutableSubject] = useState(
    initialUseImmutableSubject || isImmutableSubClaimAutoEnabled,
  )
  const [templateError, setTemplateError] = useState<string | null>(null)
  const [templateHasChanged, setTemplateHasChanged] = useState(false)
  const {setBanner} = useBannerContext()

  const {isPending: isSaving, mutate: saveSubjectClaim} = useOIDCConfigurationMutation<SubjectClaimPayload>({
    pathSuffix: 'subject-claim',
    onSuccess: () => {
      setBanner({message: 'Subject claim configuration saved successfully.', type: 'success'})
    },
  })

  const {basePath} = useConfigurationSource()

  const debouncedCheckTemplateValidity = useDebounce(async (value: string) => {
    try {
      const response = await reactFetchJSON(`${basePath}/check-template-validity`, {
        method: 'POST',
        body: {subjectClaimKeys: generateTemplateArray(value)},
      })
      if (!templateHasChanged) {
        setTemplateHasChanged(true)
      }
      if (response.ok) {
        setTemplateError('')
      } else {
        const {error} = await response.json()
        setTemplateError(error)
      }
    } catch {
      setTemplateError('Error checking template validity. Please try again.')
    }
  }, 300)

  const immutableSubjectCaption = isImmutableSubClaimAutoEnabled
    ? showDefaultTemplateOption
      ? 'Automatically enabled for this repository. Repositories created or renamed after June 1, 2026 use immutable subject claims.'
      : 'Automatically enabled for this organization.'
    : 'Improve security by including unique identifiers in the subject claim, ensuring that trust policies cannot be assumed by a different repository or organization with the same name.'

  return (
    <ClaimCustomizationSection
      title="Subject claim"
      subtitle="Customize the subject (sub) claim in the OIDC token, used to identify the workflow run context."
      onSave={() => {
        if (templateError) {
          setBanner({message: 'Please fix template errors before saving.', type: 'critical'})
          return
        }
        saveSubjectClaim({
          subjectClaimKeys: generateTemplateArray(template),
          ...(showDefaultTemplateOption && {useDefaultTemplate}),
          ...(showImmutableSubjectOption && {useImmutableSubject}),
        })
      }}
      isSaving={isSaving}
    >
      {!useDefaultTemplate && (
        <FormControl className={showDefaultTemplateOption ? styles.templateInputControl : undefined}>
          <FormControl.Label>Subject claim template</FormControl.Label>
          <Textarea
            block
            placeholder="repo, context, ref"
            rows={6}
            value={template}
            onChange={e => {
              setTemplate(e.target.value)
              debouncedCheckTemplateValidity(e.target.value)
            }}
          />
          <FormControl.Caption>
            Order-dependent list of comma-separated template variables.{' '}
            <Link inline href="https://docs.github.com/en/actions/reference/security/oidc">
              List of available template variables.
            </Link>
          </FormControl.Caption>
          {templateHasChanged && (
            <FormControl.Validation variant={templateError ? 'error' : 'success'}>
              {templateError || 'Template is valid.'}
            </FormControl.Validation>
          )}
        </FormControl>
      )}
      {showDefaultTemplateOption && (
        <FormControl>
          <Checkbox checked={useDefaultTemplate} onChange={e => setUseDefaultTemplate(e.target.checked)} />
          <FormControl.Label>Use default template</FormControl.Label>
          <FormControl.Caption>
            When selected, use upstream template for the subject claim. Unselect to set a custom template.
          </FormControl.Caption>
        </FormControl>
      )}
      {showImmutableSubjectOption && (
        <div className={styles.immutableSubjectSection}>
          <FormControl disabled={isImmutableSubClaimAutoEnabled}>
            <Checkbox checked={useImmutableSubject} onChange={e => setUseImmutableSubject(e.target.checked)} />
            <FormControl.Label>Use immutable subject claim</FormControl.Label>
            <FormControl.Caption>{immutableSubjectCaption}</FormControl.Caption>
          </FormControl>
          {immutableSubClaimPrefix && (
            <div className={styles.subClaimPrefixControl}>
              <span className={styles.snippetLabel}>Default subject claim prefix</span>
              <div className={styles.snippetRow}>
                <code className={styles.snippet}>
                  {useImmutableSubject || isImmutableSubClaimAutoEnabled ? immutableSubClaimPrefix : subClaimPrefix}
                </code>
                <CopyToClipboardButton
                  ariaLabel="Copy subject claim prefix"
                  textToCopy={
                    (useImmutableSubject || isImmutableSubClaimAutoEnabled
                      ? immutableSubClaimPrefix
                      : subClaimPrefix) ?? ''
                  }
                />
              </div>
              <span className={styles.snippetCaption}>
                Use this prefix when configuring trust policies in your cloud provider.
              </span>
            </div>
          )}
        </div>
      )}
    </ClaimCustomizationSection>
  )
}

const generateTemplateArray = (template: string): string[] => {
  return template
    .split(',')
    .map(key => key.trim())
    .filter(key => key.length > 0)
}
