import {Outlet, useSearchParams} from '@github-ui/react-router'
import {BannerProvider, useBannerContext} from '../context/BannerProvider'
import {Banner} from '@primer/react'
import {OidcConfigurationHeader} from '../components/OidcConfigurationHeader'
import {useConfigurationSource} from '../hooks/use-configuration-source'

export function LayoutRoute() {
  return (
    <BannerProvider>
      <CustomPropertyUsagesInfoBanner />
      <PageBanner />
      <OidcConfigurationHeader />
      <Outlet />
    </BannerProvider>
  )
}

function CustomPropertyUsagesInfoBanner() {
  const [searchParams, setSearchParams] = useSearchParams()
  const {settingsLevel} = useConfigurationSource()

  if (searchParams.get('custom-property-usages') !== 'true' || settingsLevel !== 'enterprise') return null
  return (
    <Banner
      className="tmp-mb-3"
      title="Custom property usages information"
      variant="info"
      hideTitle
      onDismiss={() => {
        const params = new URLSearchParams(searchParams)
        params.delete('custom-property-usages')
        setSearchParams(params, {replace: true})
      }}
      description="Custom properties used by Actions OIDC Configuration may have been included across organizations in this enterprise."
    />
  )
}

function PageBanner() {
  const {banner, setBanner, bannerRef} = useBannerContext()

  if (!banner) return null
  return (
    <Banner
      ref={bannerRef}
      className="tmp-mb-3"
      title="OIDC configuration update information"
      variant={banner.type}
      onDismiss={() => setBanner(null)}
      hideTitle
      description={banner.message}
    />
  )
}
