import {mainQuery} from '@github-ui/react-core/future/main-query'
import {actionsOidcConfigurationAppBuilder} from '../config/app-builder'

export type RepositoryOidcConfigurationResponse = {
  useDefaultTemplate: boolean
  subjectClaimKeys?: string[]
  showImmutableSubject: boolean
  useImmutableSubject?: boolean
  subClaimPrefix?: string
  immutableSubClaimPrefix?: string
  isImmutableSubClaimAutoEnabled?: boolean
}

export const repositoryOidcConfigurationRoute = actionsOidcConfigurationAppBuilder.createQueryRouteConfig(
  'repositoryOidcConfigurationRoute',
  {
    path: '/:owner/:repo/settings/actions/oidc-configuration',
    queries: [mainQuery<RepositoryOidcConfigurationResponse>()],
  },
)
